import json,urllib.request
try:
 with urllib.request.urlopen('http://127.0.0.1:17448/api/supervisor-watchdog/managed-chats?inspect=1',timeout=12) as r:d=json.load(r)
 rows=d.get('chats',[])
 keep=('id','status','openTabs','profileWorkerConnected','profileWorkerRegistrationState','generating','draftPresent','highMode','contextLimit','providerLoadError','activeAssignmentCount','compatible')
 clean=[]
 for x in rows:clean.append({k:x[k] for k in keep if k in x})
 print(json.dumps({'status':'INSPECTION_COMPLETED','count':len(clean),'rows':clean,'noProviderTextCaptured':True,'noSend':True},ensure_ascii=True)[:5000])
except Exception as e:print(json.dumps({'status':'READ_ONLY_INSPECTION_UNAVAILABLE','error':type(e).__name__,'noSend':True}))
